pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNum1, uint256 blockNum2) public {
        // Bound block numbers to reasonable range
        blockNum1 = bound(blockNum1, 1, 1000);
        blockNum2 = bound(blockNum2, blockNum1 + 1, 2000);

        // Bound timestamps: second must be >= first to allow the >= check to potentially pass even when equal
        timestamp1 = bound(timestamp1, 1, 100000);
        timestamp2 = bound(timestamp2, timestamp1, timestamp1 + 100000);

        // Ensure we start with enough ether
        vm.deal(address(this), 1000 ether);

        // First call: initial pastBlockTime is 0, so any timestamp > 0 works
        vm.warp(timestamp1);
        vm.roll(blockNum1);

        uint256 balanceBefore1 = address(c).balance;
        (bool success1, ) = address(c).call{value: 10 ether}("");

        if (success1) {
            // If call succeeds, contract should gain 10 ether (unless it self-destructs, which only happens on block numbers divisible by 15)
            uint256 balanceAfter1 = address(c).balance;
            bool shouldTransfer1 = (blockNum1 % 15 == 0);
            if (shouldTransfer1) {
                assertTrue(balanceAfter1 >= balanceBefore1 - 10 ether);  // sent 10, but might have transferred all balance to caller, so at most 0 left
            } else {
                assertTrue(balanceAfter1 == balanceBefore1 + 10 ether);
            }
        }

        // Second call: either timestamp > pastBlockTime (reference) or timestamp >= pastBlockTime (mutant)
        vm.warp(timestamp2);
        vm.roll(blockNum2);

        uint256 balanceBefore2 = address(c).balance;
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // Reference contract: if timestamp2 > pastBlockTime (which was set to timestamp1 on first success, or 0 if first failed)
        // But we need a property that holds for reference and fails for mutant
        // Property: If the first call succeeded and timestamp2 == timestamp1, the mutant will revert (due to >=), while reference succeeds.
        // But we want a general rule that always holds for reference.
        // Better: The reference never reverts when timestamp2 > pastBlockTime, mutant can revert when equal.
        // So let's test: after two calls with equal timestamps (second >= first), reference does not revert, mutant may.
        // Actually we need a property that ALWAYS holds for reference, not just this case.
        // The key difference: reference requires strict >, mutant allows >=.
        // So reference will revert when timestamp2 == pastBlockTime, mutant will not.
        // Therefore property: The call reverts if and only if timestamp2 == pastBlockTime (provided first call succeeded).
        // That holds for reference, but mutant will fail because it doesn't revert when equal.

        // Let's capture pastBlockTime after first call via the public getter
        uint256 pastBlockTimeAfterFirst = c.pastBlockTime();

        // The rule: if the first call succeeded and timestamp2 == pastBlockTimeAfterFirst, then the second call MUST revert
        // This is true for reference, false for mutant (mutant does not revert)
        if (success1 && timestamp2 == pastBlockTimeAfterFirst) {
            assertTrue(!success2, "Mutant should have reverted on equal timestamp");
        } else if (success1 && timestamp2 > pastBlockTimeAfterFirst) {
            // Second call should succeed (reference) and balance increases
            assertTrue(success2, "Reference should succeed on greater timestamp");
            if (success2) {
                uint256 balanceAfter2 = address(c).balance;
                bool shouldTransfer2 = (blockNum2 % 15 == 0);
                if (shouldTransfer2) {
                    assertTrue(balanceAfter2 >= balanceBefore2 - 10 ether);
                } else {
                    assertTrue(balanceAfter2 == balanceBefore2 + 10 ether);
                }
            }
        }
        // If first succeeded and timestamp2 < pastBlockTimeAfterFirst, both should revert (so nothing to check)
        // If first failed, pastBlockTime is 0, second behaves similarly
    }
}

