        vm.assume(blockNumber > 0 && blockNumber < 2**64);
        vm.assume(timestamp1 > 0 && timestamp1 < 2**64);
        vm.assume(timestamp2 > timestamp1 && timestamp2 < 2**64);

        // Ensure block.number is not a multiple of 15 for this test
        vm.assume(blockNumber % 15 != 0);

        // Set initial block context
        vm.warp(timestamp1);
        vm.roll(blockNumber);

        // Record initial balance
        uint256 initialBalance = address(c).balance;

        // Make the fallback call with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        // The reference C: if block.timestamp > pastBlockTime, call succeeds; else reverts.
        // For the first call, pastBlockTime is 0, so it should succeed.
        // We choose parameters to ensure success: first call with timestamp1 > 0
        vm.assume(success); // ensure the call didn't revert

        // After this call, pastBlockTime = timestamp1
        // Now perform a second call at a later timestamp
        vm.warp(timestamp2);

        uint256 balanceBeforeSecond = address(c).balance;

        (bool success2, ) = address(c).call{value: 10 ether}("");

        // If the second call succeeded (should in reference, but mutant may also succeed due to missing check)
        // The invariant we test: the balance decrease is exactly 10 ether when condition is met
        // Actually, we want a property that holds for reference but fails for mutant.
        // Mutant: deletes the timestamp check, so always succeeds (if msg.value == 10 ether)
        // Reference: requires block.timestamp > pastBlockTime, so second call at later timestamp succeeds.
        // Both succeed, so balance decrease is same. We need a different approach.

        // Instead, test that pastBlockTime is strictly increasing after each successful fallback call.
        // Reference ensures this due to require; mutant could set same timestamp.
        // But that property was already tried. Let's try a different one:
        // The contract's balance (excluding sent ether) after a successful fallback should be initial + 10 ether
        // because no transfer occurs when block.number % 15 != 0.
        // We already used that. Let's make a new rule:
        // When block.number % 15 == 0, the balance after fallback becomes 0 (all sent to msg.sender).
        // Mutant: same behavior? Actually mutant also transfers, so same. Not good.

        // Reconsider: The only difference is the removal of timestamp check.
        // So for a call with msg.value = 10 ether at a timestamp <= pastBlockTime, reference reverts, mutant succeeds.
        // We can test that: after one successful call, try another at same timestamp (so <=).
        // Reference reverts, mutant does not. Use try/catch to detect revert.

        // Let's do that properly:
        // First, reset state by deploying new contract
        // Actually we can reuse: do first call at timestamp1, then try second at same timestamp1.

